-- Generated by scripts/build-release.mjs from supabase/evolution/62_cm_economy.sql; edit that file instead.
-- Paste the WHOLE file in the Supabase SQL Editor and run it at once.
-- Not compared (intentionally compacted): cw_clubs, cw_contracts, cw_coach_contracts, cw_finance, cw_commitments, wallet_ledger, careers.
begin;
set local lock_timeout='5s';
set local statement_timeout='300s';
set local timezone='UTC';
drop table if exists public._release_protected_before;
create table public._release_protected_before(career_id uuid,table_name text,predicate text,cols text[],n bigint,hash text,primary key(career_id,table_name));
alter table public._release_protected_before enable row level security;
revoke all on public._release_protected_before from public,anon,authenticated;
do $$ declare c record;t record;pred text;h text;n bigint;begin
 perform 1 from public.careers order by id for update;
 for c in select id from public.careers order by id loop
  for t in select tab.table_name::text table_name,array_agg(col.column_name::text order by col.column_name) cols
   from information_schema.tables tab join information_schema.columns col using(table_schema,table_name)
   where tab.table_schema='public' and tab.table_type='BASE TABLE' and tab.table_name not in('_release_protected_before','cw_clubs','cw_contracts','cw_coach_contracts','cw_finance','cw_commitments','wallet_ledger','careers')
   group by tab.table_name order by tab.table_name loop
   pred:=case when t.table_name='careers' then 'id=$1' when 'career_id'=any(t.cols) then 'career_id=$1'
    when 'season_id'=any(t.cols) then 'season_id in(select id from public.career_seasons where career_id=$1)'
    when 'fixture_id'=any(t.cols) then 'fixture_id in(select f.id from public.season_fixtures f join public.career_seasons s on s.id=f.season_id where s.career_id=$1)' end;
   if pred is null then continue;end if;
   execute format('select count(*),md5(coalesce(string_agg(h,'''' order by h),'''')) from(select md5((select jsonb_object_agg(k,v) from jsonb_each(to_jsonb(x)) e(k,v) where k=any($2))::text) h from public.%I x where %s)z',t.table_name,pred) into n,h using c.id,t.cols;
   insert into public._release_protected_before values(c.id,t.table_name,pred,t.cols,n,h);
  end loop;
 end loop;
end $$;
-- Evolução 62 — finanças no modelo do Championship Manager 17.
-- O clube passa a ter só duas grandezas:
--  * Verba de transferências (coluna cash): sobe com bilheteria e prêmios por jogo, vendas, aportes do treinador e o
--    orçamento anual da diretoria; desce com taxas, luvas, bônus de transferência, obras e taxas de empréstimo.
--  * Teto salarial mensal (wage_budget): a folha (atletas + comissão contratada) não pode passar dele em contratações e
--    renovações. Salários NÃO saem da verba.
-- Saem: receita comercial e operação mensal, folha descontada do caixa, dívida, risco financeiro, plano de recuperação e
-- demissão por finanças. O salário do treinador continua sendo pago em moedas todo mês.
-- A diretoria define verba e teto no início de cada temporada (reputação do clube, confiança da diretoria e dificuldade).
-- Conversão: verba = caixa − dívida (mínimo 0); teto = maior entre folha atual +15% e a receita mensal de referência;
-- salários atrasados de atletas são perdoados e os do treinador são pagos em moedas.

alter table public.cw_clubs add column if not exists wage_budget bigint;
alter table public.sim_difficulty_profiles add column if not exists budget_mult numeric(4,2) not null default 1;
alter table public.sim_difficulty_profiles add column if not exists wage_mult numeric(4,2) not null default 1;
update public.sim_difficulty_profiles set budget_mult=case id when 'accessible' then 1.15 when 'hard' then 0.85 else 1 end,
 wage_mult=case id when 'accessible' then 1.10 when 'hard' then 0.95 else 1 end;
create table if not exists public.cw_budget_years(career_id uuid not null references public.careers(id) on delete cascade,
 region text not null,year int not null,primary key(career_id,region,year));
alter table public.cw_budget_years enable row level security;
revoke all on public.cw_budget_years from public,anon,authenticated;

-- ---------------------------------------------------------------- conversão (uma vez por clube)
do $$ declare r record;begin
 for r in select cc.career_id,cc.club_id,cc.arrears,cc.id from public.cw_coach_contracts cc where cc.arrears>0 loop
  if exists(select 1 from public.careers where id=r.career_id) then
   perform public.econ_apply(r.career_id,'coins',least(r.arrears,2000000000)::int,'coach_salary','cm-conversion:'||r.id);
  end if;
 end loop;
end $$;
update public.cw_coach_contracts set arrears=0 where arrears>0;
update public.cw_contracts set arrears=0 where arrears>0;
update public.cw_clubs c set cash=greatest(0,c.cash-c.debt),debt=0,financial_risk=0,distress_since=null,
 wage_budget=greatest(ceil(public.cw_payroll(c.career_id,c.club_id)*1.15),c.monthly_revenue)::bigint
where c.wage_budget is null;

-- ---------------------------------------------------------------- orçamento e teto
create or replace function public.cw_wage_budget(p_career uuid,p_club text)
returns bigint language sql stable security definer set search_path=public as $$
 select coalesce(wage_budget,greatest(ceil(public.cw_payroll(p_career,p_club)*1.15),monthly_revenue)::bigint) from public.cw_clubs where career_id=p_career and club_id=p_club
$$;
create or replace function public.cw_wage_room(p_career uuid,p_club text)
returns bigint language sql stable security definer set search_path=public as $$
 select public.cw_wage_budget(p_career,p_club)-public.cw_payroll(p_career,p_club)
$$;

create or replace function public.cw_available_budget(p_career uuid,p_club text)
returns bigint language sql stable security definer set search_path=public as $$
 select greatest(0,cash-public.cw_reserved(p_career,p_club)) from public.cw_clubs where career_id=p_career and club_id=p_club
$$;

-- Aumento de folha de uma negociação (o contrato atual do próprio clube já está na folha).
create or replace function public.cw_neg_wage_increment(p_id uuid)
returns bigint language sql stable security definer set search_path=public as $$
 select greatest(0,public.cw_contract_cost(n.player_id,n.monthly_salary,n.appearance_bonus,n.goal_bonus,n.role)
  -coalesce((select public.cw_contract_cost(player_id,monthly_salary,appearance_bonus,goal_bonus,role) from public.cw_contracts
   where career_id=n.career_id and player_id=n.player_id and club_id=n.buyer_club and status='active'),0))
 from public.cw_negotiations n where n.id=p_id and n.monthly_salary>0
$$;

create or replace function public.cw_can_afford_contract(p_id uuid)
returns boolean language plpgsql stable security definer set search_path=public as $$
#variable_conflict use_column
declare n public.cw_negotiations;c public.cw_clubs;
begin
 select * into n from public.cw_negotiations where id=p_id;
 select * into c from public.cw_clubs where career_id=n.career_id and club_id=n.buyer_club;
 if c.club_id is null then return false;end if;
 if coalesce(public.cw_neg_wage_increment(p_id),0)>public.cw_wage_room(n.career_id,n.buyer_club) then return false;end if;
 return c.cash-public.cw_reserved(n.career_id,n.buyer_club)
   +coalesce((select amount from public.cw_commitments where career_id=n.career_id and reference=n.id||':offer' and status='reserved'),0)
  >=n.fee+n.signing_bonus+n.performance_bonus;
end $$;

create or replace function public.cw_reserve_offer(p_id uuid)
returns void language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare n public.cw_negotiations;needed bigint;available bigint;room bigint;inc bigint;
begin
 select * into n from public.cw_negotiations where id=p_id;
 needed:=n.fee+n.signing_bonus+n.performance_bonus;
 inc:=coalesce(public.cw_neg_wage_increment(p_id),0);
 room:=public.cw_wage_room(n.career_id,n.buyer_club);
 if inc>room then
  raise exception 'O teto salarial do clube não comporta este salário (folga de %).',public.cw_money_label(greatest(0,room));
 end if;
 select public.cw_available_budget(n.career_id,n.buyer_club)+coalesce((select amount from public.cw_commitments where career_id=n.career_id and reference=n.id||':offer'),0) into available;
 if needed>available then raise exception 'Verba de transferências insuficiente para taxa, luvas e bônus';end if;
 insert into public.cw_commitments(career_id,club_id,negotiation_id,kind,amount,due_on,reference)
 values(n.career_id,n.buyer_club,n.id,'offer',needed,n.expires_on,n.id||':offer')
 on conflict(career_id,club_id,reference) do update set amount=excluded.amount,status='reserved',due_on=excluded.due_on;
end $$;

-- ---------------------------------------------------------------- mês: sem folha descontada; salário do treinador em moedas
create or replace function public.cw_settle_month(p_career uuid,p_month date)
returns void language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare month_end date:=(p_month+interval '1 month - 1 day')::date;month_days int;st public.cw_coach_contracts;due bigint;overlap int;
begin
 perform 1 from public.careers where id=p_career for update;
 if not exists(select 1 from public.cw_settled_months where career_id=p_career and month=p_month) then
  insert into public.cw_settled_months(career_id,month) values(p_career,p_month) on conflict do nothing;
  month_days:=month_end-p_month+1;
  for st in select * from public.cw_coach_contracts where career_id=p_career and starts_on<=month_end and coalesce(ended_on,expires_on)>=p_month order by id loop
   overlap:=greatest(0,least(month_end,st.expires_on,coalesce(st.ended_on,st.expires_on))-greatest(p_month,st.starts_on)+1);
   due:=round(st.monthly_salary*overlap::numeric/month_days);
   if due>0 then perform public.econ_apply(p_career,'coins',least(due,2000000000)::int,'coach_salary',st.id::text||':'||to_char(p_month,'YYYY-MM'));end if;
  end loop;
  if not public.cw_runtime_enabled(p_career) then perform public.cw_compact_month(p_career,p_month);end if;
 end if;
 begin
  perform public.cw_dev_month(p_career,p_month);
 exception when others then perform public.cw_dev_log(p_career,'month',sqlerrm);
 end;
 begin
  perform public.cw_board_budget(p_career,p_month);
 exception when others then perform public.cw_dev_log(p_career,'budget',sqlerrm);
 end;
end $$;

-- Sem risco financeiro, recuperação ou demissão por finanças; contratos vencidos seguem sendo encerrados.
create or replace function public.cw_finance_tick(p_career uuid)
returns void language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare w public.cw_world;coach public.mgr_coach;ct public.cw_contracts;
begin
 perform public.cw_prepare_club_economy(p_career);
 perform public.cw_ai_contracts_tick(p_career);
 select * into w from public.cw_world where career_id=p_career;
 if extract(day from w.today)=1 then perform public.cw_settle_month(p_career,(date_trunc('month',w.today)-interval '1month')::date);end if;
 select * into coach from public.mgr_coach where career_id=p_career;
 for ct in select * from public.cw_contracts where career_id=p_career and status='active' and expires_on<w.today
  and(not public.cw_runtime_enabled(p_career) or club_id=coach.club_id or club_id in(select public.cw_domestic_clubs(p_career))
   or exists(select 1 from public.cw_negotiations n where n.career_id=p_career and n.player_id=cw_contracts.player_id and n.status='precontract')) for update loop
  update public.cw_contracts set status='expired',ended_on=expires_on where id=ct.id;
  update public.mgr_players set club_id=null where career_id=p_career and player_id=ct.player_id and club_id=ct.club_id;
  perform public.cw_prune_lineups(p_career,ct.player_id);
  perform public.cw_news_add(p_career,'expiry:'||ct.id,'contract',public.mgr_player_name(ct.player_id)||' encerra seu contrato',
   'O atleta está livre após o encerramento do vínculo com '||public.mgr_club_name(ct.club_id)||'.',case when ct.club_id=coach.club_id then 85 else 30 end,ct.club_id,ct.player_id);
 end loop;
end $$;

-- Orçamento anual da diretoria, no início da temporada de cada região (verba + teto).
create or replace function public.cw_board_budget(p_career uuid,p_month date)
returns void language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare reg text;yr int;c record;own text;conf numeric;diff public.sim_difficulty_profiles;grant_v bigint;wage bigint;payroll bigint;excess bigint;
begin
 select club_id into own from public.mgr_coach where career_id=p_career and status='employed';
 select coalesce(board_confidence,60) into conf from public.mgr_coach where career_id=p_career;
 diff:=public.mgr_difficulty(p_career);
 foreach reg in array array['BRA','ENG'] loop
  continue when extract(month from p_month)<>(case when reg='ENG' then 7 else 1 end);
  yr:=extract(year from p_month)::int;
  insert into public.cw_budget_years(career_id,region,year) values(p_career,reg,yr) on conflict do nothing;
  continue when not found;
  for c in select cc.* from public.cw_clubs cc where cc.career_id=p_career and public.cw_region(cc.club_id)=reg
   and (cc.club_id=own or cc.club_id in(select public.cw_domestic_clubs(p_career))) order by cc.club_id loop
   payroll:=public.cw_payroll(p_career,c.club_id);
   if c.club_id=own then
    grant_v:=round(c.monthly_revenue*4*coalesce(diff.budget_mult,1)*(.8+.4*least(100,greatest(0,conf))/100));
    wage:=round(greatest(payroll*1.10,c.monthly_revenue)*coalesce(diff.wage_mult,1));
   else
    grant_v:=round(c.monthly_revenue*3);
    wage:=round(greatest(payroll*1.15,c.monthly_revenue*1.05));
   end if;
   perform public.cw_cash(p_career,c.club_id,grant_v,'board_budget',reg||':'||yr,'Orçamento da diretoria para a temporada');
   update public.cw_clubs set wage_budget=wage where career_id=p_career and club_id=c.club_id;
   if c.club_id<>own then
    -- clubes da IA não acumulam verba sem fim: o excedente vira patrimônio (estrutura)
    select greatest(0,cash-4*initial_budget) into excess from public.cw_clubs where career_id=p_career and club_id=c.club_id;
    if excess>0 then
     perform public.cw_cash(p_career,c.club_id,-excess,'infrastructure',reg||':'||yr,'Investimento patrimonial da diretoria');
     update public.cw_clubs set infrastructure=infrastructure+excess where career_id=p_career and club_id=c.club_id;
    end if;
   else
    perform public.cw_inbox_add(p_career,'budget:'||reg||':'||yr,'board','club','Orçamento da temporada',
     'A diretoria liberou '||public.cw_money_label(grant_v)||' para transferências e definiu o teto salarial em '||public.cw_money_label(wage)
     ||' por mês. Bilheteria, prêmios e vendas aumentam a verba ao longo da temporada.',own,null,null,'open_finance');
   end if;
  end loop;
 end loop;
end $$;

-- A comissão contratada entra na folha (teto) e não é mais descontada da verba; empréstimos idem.
do $$ declare src text;o1 text;o2 text;begin
 select pg_get_functiondef('public.cw_dev_month(uuid,date)'::regprocedure) into src;
 if src not like '%Salários da comissão técnica%' then return;end if;
 o1:=substring(src from '(\n -- salários da comissão contratada.*?end loop;)');
 o2:=substring(src from '(\n -- empréstimos: o clube de origem paga.*?end loop;)');
 if o1 is null or o2 is null then raise exception 'cw_dev_month diferente do esperado';end if;
 src:=replace(src,o1,'');src:=replace(src,o2,'');
 execute src;
end $$;

create or replace function public.cw_payroll(p_career uuid,p_club text)
returns bigint language sql stable security definer set search_path=public as $$
 select (select coalesce(sum(public.cw_contract_cost(player_id,monthly_salary,appearance_bonus,goal_bonus,role)),0) from public.cw_contracts where career_id=p_career and club_id=p_club and status='active')
  +(select coalesce(sum(monthly_salary),0) from public.cw_coach_contracts where career_id=p_career and club_id=p_club and ended_on is null and expires_on>=(select today from public.cw_world where career_id=p_career))
  +coalesce((select sum(monthly_salary) from public.cw_staff where career_id=p_career and club_id=p_club),0)
$$;

-- Cotação de aporte: o que falta é só taxa + luvas + bônus (salário não sai da verba); o teto salarial vira motivo de bloqueio.
do $$ declare src text;begin
 select pg_get_functiondef('public.cw_funding_quote(uuid,text,uuid,jsonb)'::regprocedure) into src;
 if src like '%cw_wage_room%' then return;end if;
 if position('needed:=fee+signing+performance+greatest(6,months)*increment;' in src)=0
  or position('gap:=greatest(0,needed+months*payroll+c.debt+reserved-previous_reserve-c.cash);' in src)=0
  or position($q$'salary_reserve',greatest(6,months)*increment,'current_payroll_reserve',months*payroll,$q$ in src)=0
  or position($q$'required_cash',needed+months*payroll+c.debt+reserved-previous_reserve,$q$ in src)=0 then
  raise exception 'cw_funding_quote diferente do esperado';
 end if;
 src:=replace(src,'needed:=fee+signing+performance+greatest(6,months)*increment;','needed:=fee+signing+performance;');
 src:=replace(src,'gap:=greatest(0,needed+months*payroll+c.debt+reserved-previous_reserve-c.cash);',
  'gap:=greatest(0,needed+reserved-previous_reserve-c.cash);'||chr(10)||
  ' if reason is null and increment>public.cw_wage_room(p_career,own) then reason:=''O teto salarial do clube não comporta este salário (folga de ''||public.cw_money_label(greatest(0,public.cw_wage_room(p_career,own)))||''). Libere salários ou aguarde o orçamento da próxima temporada.'';end if;');
 src:=replace(src,$q$'salary_reserve',greatest(6,months)*increment,'current_payroll_reserve',months*payroll,$q$,$q$'salary_reserve',0,'current_payroll_reserve',0,'wage_room',public.cw_wage_room(p_career,own),'wage_budget',public.cw_wage_budget(p_career,own),$q$);
 src:=replace(src,$q$'required_cash',needed+months*payroll+c.debt+reserved-previous_reserve,$q$,$q$'required_cash',needed+reserved-previous_reserve,$q$);
 execute src;
end $$;


-- Comissão, empréstimos e obras usam o teto salarial e a verba (sem risco financeiro).
create or replace function public.career_staff_hire(p_role text,p_level int,p_request uuid)
returns jsonb language plpgsql security definer set search_path=public as $$
declare car public.careers;own text;prev jsonb;s public.cw_staff;sal bigint;res jsonb;today date;avail bigint;
begin
 car:=public.mgr_lock();own:=public.cw_dev_own(car.id);
 prev:=public.econ_request_get(car.id,p_request,'staff_hire');if prev is not null then return prev;end if;
 perform public.cw_dev_ensure_club(car.id,own);
 select * into s from public.cw_staff where career_id=car.id and club_id=own and role=p_role for update;
 if not found or p_level not between 1 and 5 then raise exception 'Cargo ou nível inválido';end if;
 select w0.today into today from public.cw_world w0 where w0.career_id=car.id;
 sal:=public.cw_staff_salary(p_level);avail:=public.cw_available_budget(car.id,own);
 if p_level=s.level then
  res:=jsonb_build_object('ok',false,'approved',false,'reason','Este profissional já está no cargo.');
 elsif p_level>s.level and public.cw_wage_room(car.id,own)<sal-s.monthly_salary then
  res:=jsonb_build_object('ok',false,'approved',false,'reason','A diretoria recusou: o teto salarial não comporta o novo salário ('||public.cw_money_label(sal)||' por mês). Como melhorar: libere salários do elenco ou aguarde o orçamento da próxima temporada.');
 else
  update public.cw_staff set level=p_level,monthly_salary=case when p_level<=initial_level then 0 else sal end,hired_on=today
  where career_id=car.id and club_id=own and role=p_role;
  res:=jsonb_build_object('ok',true,'approved',true,'monthly_salary',case when p_level<=s.initial_level then 0 else sal end);
 end if;
 return public.econ_request_save(car.id,p_request,'staff_hire',res);
end $$;

create or replace function public.career_loan_request(p_player text,p_wage_share numeric,p_role text,p_request uuid)
returns jsonb language plpgsql security definer set search_path=public as $$
declare car public.careers;own text;prev jsonb;parent text;today date;rk int;age int;reason text;lid uuid;res jsonb;sal bigint;
begin
 car:=public.mgr_lock();own:=public.cw_dev_own(car.id);
 prev:=public.econ_request_get(car.id,p_request,'loan_request');if prev is not null then return prev;end if;
 if not (select loans_enabled from public.cw_dev_rules) then raise exception 'Empréstimos indisponíveis';end if;
 if p_wage_share not between .25 and 1 or p_role not in('key','starter','rotation','prospect') then raise exception 'Condições inválidas';end if;
 select w0.today into today from public.cw_world w0 where w0.career_id=car.id;
 perform public.cw_materialize_club(car.id,public.cw_effective_player_club(car.id,p_player));
 select club_id into parent from public.mgr_players where career_id=car.id and player_id=p_player;
 if parent is null then raise exception 'Atleta sem clube: faça uma proposta de contrato.';end if;
 if parent=own then raise exception 'O atleta já é do seu elenco';end if;
 if not public.cw_window_open(public.cw_region(own),today) then raise exception 'Janela de transferências fechada.';end if;
 select ct.monthly_salary into sal from public.cw_contracts ct where ct.career_id=car.id and ct.player_id=p_player and ct.club_id=parent and ct.status='active';
 rk:=public.cw_squad_rank(car.id,parent,p_player);
 select cp.age_at_start+floor((w.today-w.started_on)/365.25)::int into age from public.cw_players cp join public.cw_world w on w.career_id=cp.career_id where cp.career_id=car.id and cp.player_id=p_player;
 reason:=public.cw_project_reason(car.id,p_player,own);
 if exists(select 1 from public.cw_loans where career_id=car.id and player_id=p_player and status in('active','offered')) then
  reason:='O atleta já está emprestado ou em negociação de empréstimo.';
 elsif sal is null then reason:='O atleta não tem contrato ativo com o clube.';
 elsif rk<=14 then reason:=public.mgr_club_name(parent)||' não empresta atletas que fazem parte do time principal. Como melhorar: procure jovens ou reservas (fora dos 14 melhores do elenco).';
 elsif coalesce(age,25)>27 and rk<=20 then reason:=public.mgr_club_name(parent)||' prefere manter seus veteranos no elenco.';
 elsif p_wage_share<(case when rk<=18 then .75 else .5 end) then reason:=public.mgr_club_name(parent)||' exige que você pague ao menos '||(case when rk<=18 then 75 else 50 end)||'% do salário. Como melhorar: aumente a parte do salário assumida.';
 elsif p_role in('rotation','prospect') and rk<=18 then reason:='O atleta só aceita o empréstimo com promessa de ser titular. Como melhorar: ofereça o papel de titular.';
 elsif public.cw_wage_room(car.id,own)<round(sal*p_wage_share) then reason:='O teto salarial do clube não comporta a parte do salário. Como melhorar: libere salários ou assuma uma parte menor.';
 elsif public.cw_squad_count(car.id,own)>=public.cw_squad_limit() then reason:='Seu elenco atingiu o limite de inscritos.';
 end if;
 if reason is not null then
  res:=jsonb_build_object('ok',false,'approved',false,'reason',reason);
 else
  insert into public.cw_loans(career_id,player_id,parent_club,borrower_club,origin,status,wage_share,role,created_on,ends_on,expires_on,response)
  values(car.id,p_player,parent,own,'user_request','offered',p_wage_share,p_role,today,public.cw_season_end(public.cw_region(own),today),today,'Acordo fechado com o clube e o atleta.')
  returning id into lid;
  perform public.cw_loan_start(lid);
  res:=jsonb_build_object('ok',true,'approved',true,'loan_id',lid,'ends_on',(select ends_on from public.cw_loans where id=lid));
 end if;
 return public.econ_request_save(car.id,p_request,'loan_request',res);
end $$;

create or replace function public.career_facility_upgrade(p_kind text,p_request uuid)
returns jsonb language plpgsql security definer set search_path=public as $$
declare car public.careers;own text;prev jsonb;f public.cw_facilities;v_cost bigint;club public.cw_clubs;today date;fund bigint;cash_part bigint;res jsonb;avail bigint;
begin
 car:=public.mgr_lock();own:=public.cw_dev_own(car.id);
 prev:=public.econ_request_get(car.id,p_request,'facility_upgrade');if prev is not null then return prev;end if;
 perform public.cw_dev_ensure_club(car.id,own);
 select * into f from public.cw_facilities where career_id=car.id and club_id=own and kind=p_kind for update;
 if not found then raise exception 'Instalação inválida';end if;
 select w0.today into today from public.cw_world w0 where w0.career_id=car.id;
 if f.building_until is not null then
  res:=jsonb_build_object('ok',false,'approved',false,'reason','Já existe uma obra em andamento nesta instalação. Conclusão prevista para '||to_char(f.building_until,'DD/MM/YYYY')||'.');
 elsif f.level>=5 then
  res:=jsonb_build_object('ok',false,'approved',false,'reason','Esta instalação já está no nível máximo.');
 else
  v_cost:=public.cw_facility_cost(p_kind,f.level+1,own);
  select * into club from public.cw_clubs where career_id=car.id and club_id=own for update;
  avail:=public.cw_available_budget(car.id,own);
  fund:=least(club.infrastructure,v_cost);cash_part:=v_cost-fund;
   if cash_part>avail then
   res:=jsonb_build_object('ok',false,'approved',false,'cost',v_cost,'reason','A diretoria recusou: faltam '||public.cw_money_label(cash_part-avail)||' de verba livre. Como melhorar: aumente a verba (vendas, prêmios, aporte) ou aguarde o fundo de infraestrutura crescer.');
  else
   if fund>0 then update public.cw_clubs set infrastructure=infrastructure-fund where career_id=car.id and club_id=own;end if;
   if cash_part>0 then perform public.cw_cash(car.id,own,-cash_part,'facility',p_request::text,'Obra aprovada: '||p_kind||' nível '||(f.level+1));end if;
   update public.cw_facilities set target_level=f.level+1,started_on=today,building_until=(today+make_interval(months=>public.cw_facility_months(p_kind,f.level+1)))::date,cost=v_cost
   where career_id=car.id and club_id=own and kind=p_kind;
   res:=jsonb_build_object('ok',true,'approved',true,'cost',v_cost,'from_fund',fund,'from_cash',cash_part,
    'building_until',(today+make_interval(months=>public.cw_facility_months(p_kind,f.level+1)))::date);
  end if;
 end if;
 return public.econ_request_save(car.id,p_request,'facility_upgrade',res);
end $$;

do $$ declare f text;begin
 foreach f in array array['cw_wage_budget(uuid,text)','cw_wage_room(uuid,text)','cw_available_budget(uuid,text)','cw_neg_wage_increment(uuid)',
  'cw_can_afford_contract(uuid)','cw_reserve_offer(uuid)','cw_settle_month(uuid,date)','cw_finance_tick(uuid)','cw_board_budget(uuid,date)',
  'cw_dev_month(uuid,date)','cw_payroll(uuid,text)'] loop
  execute format('revoke all on function public.%s from public,anon,authenticated',f);
 end loop;
end $$;

notify pgrst,'reload schema';

do $$ declare r record;h text;n bigint;begin
 if not exists(select 1 from public._release_protected_before) and exists(select 1 from public.careers) then
  raise exception 'Snapshot de preservação ausente; execute o arquivo inteiro de uma vez';
 end if;
 for r in select * from public._release_protected_before order by career_id,table_name loop
  execute format('select count(*),md5(coalesce(string_agg(h,'''' order by h),'''')) from(select md5((select jsonb_object_agg(k,v) from jsonb_each(to_jsonb(x)) e(k,v) where k=any($2))::text) h from public.%I x where %s)z',r.table_name,r.predicate) into n,h using r.career_id,r.cols;
  if n<>r.n or h<>r.hash then raise exception 'Protected progress differs in table %; deployment rolled back',r.table_name;end if;
 end loop;
 raise notice 'Protected progress verified for % careers, % table comparisons',(select count(distinct career_id) from public._release_protected_before),(select count(*) from public._release_protected_before);
end $$;
drop table public._release_protected_before;
notify pgrst,'reload schema';
commit;
